-- Quiz JOWES na Forum Współpracy Przedsiębiorstw Społecznych (19.11.2026), z pliku od zespołu JOWES
-- (quiz-sieciujacy-jowes.md): ta sama treść jako quiz klasyczny i jako wyścig. Plansze („tablice”) to ciekawostki
-- zaraz po pytaniu, którego dotyczą; wyjaśnienia w `dane.wyjasnienie` (TV po odsłonięciu odpowiedzi).
-- Oba w lokalu JOWES, udostępnione (widzi je konto lokalu), autor: konto twórcy.

-- ===== Jak dobrze znasz JOWES i siebie nawzajem? (quiz klasyczny) =====
with q as (
  insert into public.quizy (tytul, opis, lokal_id, autor_konto_id, udostepniony, tagi)
  select 'Jak dobrze znasz JOWES i siebie nawzajem? (quiz klasyczny)', 'Forum Współpracy Przedsiębiorstw Społecznych, 19.11.2026', l.id, k.id, true, array['JOWES']
    from public.lokale l, public.konta k
   where l.adres_ekranu = 'jowes' and k.email = 'l.nowak@bractwopiwne.pl'
     and not exists (select 1 from public.quizy where tytul = 'Jak dobrze znasz JOWES i siebie nawzajem? (quiz klasyczny)' and usunieto is null)
  returning id
)
insert into public.zadania (quiz_id, nr, typ, tresc, czas_s, dane, etap_id)
select q.id, v.nr, v.typ, v.tresc, v.czas_s, v.dane, null::uuid from q, (values
  (1, 'pary', 'Połącz osobę z zespołu JOWES z jej stanowiskiem.', 45, '{"lewe": ["Emilia Konstanciak", "Mariusz Kowasz", "Łukasz Bednarczyk", "Zbyszko Kabziński", "Magdalena Trzepizur"], "prawe": ["Doradca marketingowy", "Kierownik JOWES", "Animator", "Doradca kluczowy: szkolenia i kontakty z KGW", "Doradca kluczowy: sprawy formalno-księgowe"], "poprawna": [1, 4, 3, 0, 2], "wyjasnienie": "Pełny skład i role: jowes.pl/nasz-zespol."}'::jsonb),
  (2, 'wielokrotny', 'Podchwytliwe! Zaznacz WSZYSTKIE lokale gastronomiczne z subregionu północnego, które prowadzi przedsiębiorstwo społeczne ze statusem PS.', 40, '{"odpowiedzi": ["Pieczone Kopytko", "Stowarzyszenie Muzeum 303 im. ppłk. pil. Jana Zumbacha", "Klubokawiarnia Alternatywa 21", "Firma Handlowo-Usługowa SIN-BUD sp. z o.o.", "Art of Dining", "Fundacja Rething", "Niebo w Mieście Częstochowa"], "poprawna": [0, 6], "wyjasnienie": "Status PS mają Pieczone Kopytko (Fundacja Talbota) i Niebo w Mieście. Pułapki: Klubokawiarnię Alternatywa 21 prowadzi ZAZ, a nie PS. Art of Dining to gastronomia z misją, ale status PS dopiero uzyska."}'::jsonb),
  (3, 'ciekawostka', 'Gastronomia z misją – gdzie zjeść i co robią', null, '{"tekst": "Pieczone Kopytko (Fundacja Talbota) · Częstochowa, ul. Powstańców Warszawy 147\nTradycyjna kuchnia polska, specjalność: ręcznie robione pieczone kopytka. Pomaga osobom wykluczonym wrócić do pracy.\n\nNiebo w Mieście · Częstochowa, ul. Targowa 1\nRestauracja i kawiarnia z kuchnią włoską w zabytkowej kamienicy. Imprezy okolicznościowe i dowóz.\n\nPułapka z pytania: Alternatywa 21 (ul. Przemysłowa 14/16) to klubokawiarnia prowadzona przez ZAZ, a nie przez PS. Art of Dining status PS dopiero uzyska – trzymamy kciuki!"}'::jsonb),
  (4, 'wybor', 'Jaki jest adres naszej strony internetowej?', 20, '{"odpowiedzi": ["jowes.org", "jowes.com", "jowes.pl", "jowes.czestochowa.pl"], "poprawna": 2, "wyjasnienie": "Oficjalna strona to jowes.pl – tam są aktualności, baza PES, zespół i nabory dotacji."}'::jsonb),
  (5, 'wybor', 'Czym działalność odpłatna pożytku publicznego różni się od działalności gospodarczej w fundacji lub stowarzyszeniu?', 40, '{"odpowiedzi": ["Niczym – to dwie nazwy tej samej działalności.", "W działalności odpłatnej nie wolno zatrudniać pracowników, w gospodarczej już tak.", "Odpłatną może prowadzić tylko spółdzielnia socjalna, a gospodarczą tylko fundacja.", "Odpłatna nie może przynosić zysku (cena pokrywa najwyżej koszty bezpośrednie), a gospodarcza może i wymaga wpisu do rejestru przedsiębiorców KRS."], "poprawna": 3, "wyjasnienie": "Działalność odpłatna to zadania pożytku publicznego za opłatą – bez zysku. Gdy cena przekroczy koszty bezpośrednie, z mocy ustawy staje się gospodarczą. Gospodarcza może dawać zysk na cele statutowe, ale wymaga wpisu do rejestru przedsiębiorców KRS."}'::jsonb),
  (6, 'ciekawostka', 'Odpłatna czy gospodarcza? Ściąga', null, '{"tekst": "Działalność odpłatna pożytku publicznego\n• Tylko zadania pożytku publicznego wpisane do statutu.\n• Cena najwyżej na poziomie kosztów bezpośrednich – bez zysku.\n• Cały przychód idzie na działalność pożytku publicznego.\n• Nie wymaga wpisu do rejestru przedsiębiorców.\n\nDziałalność gospodarcza\n• Może przynosić zysk – w NGO idzie on na cele statutowe.\n• Wymaga wpisu do rejestru przedsiębiorców KRS.\n\nUwaga: gdy cena w odpłatnej przekroczy koszty bezpośrednie, z mocy prawa staje się ona gospodarczą (art. 9 ustawy o działalności pożytku publicznego i o wolontariacie).\nPrzykład: warsztat kosztuje 50 zł od osoby. Bilet za 50 zł = odpłatna, za 80 zł = gospodarcza."}'::jsonb),
  (7, 'wybor', 'Który z wymienionych instrumentów zwrotnych (pożyczek) jest dostępny dla podmiotów ekonomii społecznej?', 35, '{"odpowiedzi": ["1. Pożyczka rozwojowa udzielana przez Agencję Rozwoju Regionalnego w Częstochowie", "2. Pożyczka na start i na rozwój udzielana przez Towarzystwo Inwestycji Społeczno-Ekonomicznych", "Żadna z powyższych", "Zarówno 1, jak i 2"], "poprawna": 3, "wyjasnienie": "Obie! Pożyczka rozwojowa ARR jest dla PES prowadzących działalność gospodarczą (jak dla MŚP), a TISE udziela preferencyjnych pożyczek „na start” i „na rozwój” właśnie podmiotom ekonomii społecznej."}'::jsonb),
  (8, 'wybor', 'Ile wynosi oprocentowanie preferencyjnej pożyczki TISE?', 20, '{"odpowiedzi": ["0,25%", "2%", "1,5%", "3%"], "poprawna": 0, "wyjasnienie": "Stałe 0,25% w skali roku, bez prowizji i bez kosztów administracyjnych."}'::jsonb),
  (9, 'wybor', 'Ile wynosi oprocentowanie pożyczki rozwojowej z ARR w Częstochowie?', 20, '{"odpowiedzi": ["0,25%", "5%", "2%", "8%"], "poprawna": 2, "wyjasnienie": "2% w skali roku, stałe – to oprocentowanie preferencyjne, udzielane w ramach pomocy de minimis."}'::jsonb),
  (10, 'wybor', 'Jaką maksymalną kwotę można pożyczyć w ramach pożyczki rozwojowej ARR?', 20, '{"odpowiedzi": ["500 tys. zł", "5 mln zł", "1 mln zł", "2 mln zł"], "poprawna": 1, "wyjasnienie": "Do 5 mln zł, z możliwością sfinansowania nawet 100% inwestycji, w kwotach brutto (z VAT)."}'::jsonb),
  (11, 'wybor', 'Na ile lat maksymalnie TISE udziela pożyczki „na rozwój” powyżej 400 tys. zł?', 20, '{"odpowiedzi": ["3 lata", "5 lat", "7 lat", "10 lat"], "poprawna": 3, "wyjasnienie": "Do 10 lat. Pożyczki „na rozwój” do 400 tys. zł spłaca się do 7 lat, a pożyczkę „na start” – do 5 lat."}'::jsonb),
  (12, 'wybor', 'Która pożyczka daje dłuższą karencję w spłacie kapitału?', 30, '{"odpowiedzi": ["Pożyczka TISE – do 12 miesięcy", "Pożyczka rozwojowa ARR – do 12 miesięcy", "Obie – do 24 miesięcy", "Żadna nie przewiduje karencji"], "poprawna": 1, "wyjasnienie": "ARR daje do 12 miesięcy karencji, TISE – do 6 miesięcy. Karencja to czas, w którym nie spłacacie jeszcze kapitału."}'::jsonb),
  (13, 'wybor', 'Na co NIE można przeznaczyć preferencyjnej pożyczki TISE?', 25, '{"odpowiedzi": ["Zakup samochodu dostawczego", "Utworzenie nowego miejsca pracy", "Spłatę innego kredytu lub pożyczki", "Modernizację maszyn i urządzeń"], "poprawna": 2, "wyjasnienie": "Pożyczka nie spłaci starych długów. Wykluczone są też wkład własny i VAT do projektów UE oraz prefinansowanie projektów unijnych."}'::jsonb),
  (14, 'wybor', 'Jakie zabezpieczenie jest obowiązkowe przy każdej pożyczce TISE?', 20, '{"odpowiedzi": ["Weksel", "Hipoteka na nieruchomości", "Gwarancja bankowa", "Żadne – pożyczka jest bez zabezpieczeń"], "poprawna": 0, "wyjasnienie": "Weksel jest obligatoryjny. Dodatkowo stosuje się m.in. poręczenie wekslowe, przewłaszczenie lub zastaw rejestrowy na środkach trwałych albo hipotekę."}'::jsonb),
  (15, 'ciekawostka', 'Pożyczki dla PES – ściąga', null, '{"tekst": "Pożyczka rozwojowa ARR Częstochowa\n• Do 5 mln zł, do 100% inwestycji (brutto).\n• Oprocentowanie 2% stałe (de minimis).\n• Spłata do 84 miesięcy, karencja do 12 miesięcy.\n• Decyzja do 14 dni roboczych od złożenia kompletu.\n\nPreferencyjna pożyczka TISE\n• „Na start” (1. rok): max 2 × 100 tys. zł, spłata do 5 lat.\n• „Na rozwój”: do 2 mln zł, spłata do 7 lat (do 10 lat powyżej 400 tys. zł).\n• Oprocentowanie 0,25% stałe, bez prowizji i opłat.\n• Karencja do 6 miesięcy, weksel obowiązkowo.\n\nNabór na pożyczkę rozwojową ARR trwa od 6.11.2026 – pula 20,5 mln zł."}'::jsonb),
  (16, 'wybor', 'Ile miejsc pracy powstało w PES/PS dzięki JOWES od 2013 roku?', 20, '{"odpowiedzi": ["352", "248", "570", "610"], "poprawna": 2, "wyjasnienie": "570 miejsc pracy i ponad 28,6 mln zł dotacji dla NGO we wszystkich czterech edycjach JOWES (od 2013 r.). Sam obecny projekt (od 2024 r.) to już 177 miejsc pracy."}'::jsonb),
  (17, 'wielokrotny', 'Podchwytliwe! Które formy wsparcia JOWES organizuje cyklicznie? Zaznacz wszystkie poprawne.', 30, '{"odpowiedzi": ["Rajd Podmiotów Ekonomii Społecznej", "NGO w Akcji", "Forum Współpracy Przedsiębiorstw Społecznych", "NGO Marketing Days"], "poprawna": [0, 1, 2, 3], "wyjasnienie": "Wszystkie cztery! Rajd PES, NGO w Akcji, Forum Współpracy Przedsiębiorstw Społecznych (właśnie na nim jesteśmy) i NGO Marketing Days – coroczne spotkanie o marketingu, organizowane od 2015 roku."}'::jsonb),
  (18, 'wybor', 'Ile osób co najmniej musi zatrudniać przedsiębiorstwo społeczne?', 20, '{"odpowiedzi": ["1", "5", "8", "3"], "poprawna": 3, "wyjasnienie": "Minimum 3 osoby na umowę o pracę lub spółdzielczą umowę o pracę, co najmniej na ¼ etatu. Co najmniej 30% zatrudnionych to osoby z grup zagrożonych wykluczeniem."}'::jsonb),
  (19, 'wybor', 'Kto jest właściwy do nadania statusu przedsiębiorstwa społecznego?', 25, '{"odpowiedzi": ["Prezydent miasta właściwy dla siedziby organizacji", "Wojewoda", "Starosta właściwy dla miejsca prowadzenia działalności", "Marszałek województwa"], "poprawna": 1, "wyjasnienie": "Status PS nadaje wojewoda w drodze decyzji administracyjnej, według siedziby podmiotu – u nas to Wojewoda Śląski."}'::jsonb),
  (20, 'wybor', 'Ile wynosi łączne wsparcie na utworzenie i utrzymanie jednego pełnoetatowego miejsca pracy w naborze 2026?', 25, '{"odpowiedzi": ["87 068 zł", "65 000 zł", "75 000 zł", "98 015 zł"], "poprawna": 0, "wyjasnienie": "43 814 zł na utworzenie + 43 254 zł na utrzymanie przez 12 miesięcy = 87 068 zł. Szczegóły na następnej planszy."}'::jsonb),
  (21, 'ciekawostka', 'Skąd się bierze 87 068 zł?', null, '{"tekst": "  43 814 zł – utworzenie miejsca pracy (wyposażenie, sprzęt, adaptacja, środki obrotowe)\n+ 43 254 zł – utrzymanie: pełny etat przez 12 miesięcy (wynagrodzenie, składki, czynsz, media)\n= 87 068 zł na jedno pełnoetatowe miejsce pracy\n\n• Obie stawki bierze się tylko łącznie.\n• Trwałość: 12 miesięcy utrzymania + 6 miesięcy po finansowaniu = 18 miesięcy.\n• Niepełny etat: ¾ etatu – 32 441 zł, ½ etatu – 21 627 zł.\n• Jeden PS może w naborze dostać wsparcie na maks. 5 miejsc pracy.\n• Dodatkowo: refundacja Indywidualnego Planu Reintegracji do 10 800 zł.\n\nKwoty to stawki jednostkowe po indeksacji – źródło: jowes.pl/dotacje2026."}'::jsonb),
  (22, 'wybor', 'Rozwiń właściwie skrót: CIS', 20, '{"odpowiedzi": ["Taxus – rodzaj roślin z rodziny cisowatych", "Częstochowska Izba Społeczna", "Centralna Innowacja Społeczna", "Centrum Integracji Społecznej"], "poprawna": 3, "wyjasnienie": "Centrum Integracji Społecznej to placówka realizująca program reintegracji społeczno-zawodowej dla osób zagrożonych wykluczeniem społecznym."}'::jsonb),
  (23, 'wybor', 'Czy podmiot ekonomii społecznej może utworzyć i prowadzić Centrum Integracji Społecznej (CIS)?', 35, '{"odpowiedzi": ["Nie, CIS mogą tworzyć wyłącznie samorządy (wójt, burmistrz, prezydent miasta).", "Tak, bez żadnych dodatkowych warunków i formalności.", "Tak, pod warunkiem, że jest to organizacja pozarządowa lub spółdzielnia socjalna.", "Nie, ponieważ prowadzenie CIS jest zarezerwowane wyłącznie dla urzędów pracy."], "poprawna": 2, "wyjasnienie": "CIS może utworzyć m.in. organizacja pozarządowa lub spółdzielnia socjalna osób prawnych – ale potrzebna jest decyzja wojewody o nadaniu statusu CIS. Szczegóły na następnej planszy."}'::jsonb),
  (24, 'ciekawostka', 'Kto może utworzyć CIS?', null, '{"tekst": "• Organizacje pozarządowe – np. fundacje i stowarzyszenia.\n• Podmioty kościelne.\n• Spółdzielnie socjalne zakładane przez osoby prawne.\n\nUwaga: utworzenie CIS wymaga decyzji wojewody o nadaniu statusu Centrum Integracji Społecznej."}'::jsonb),
  (25, 'pary', 'Połącz podmiot ekonomii społecznej z jego branżą.', 40, '{"lewe": ["Fundacja Algiz", "Kinesis Sp. z o.o.", "Fundacja Art of Dining", "Fundacja Q Marzeniom"], "prawe": ["Gastronomia", "Usługi eventowo-szkoleniowe", "Wczesne wspomaganie rozwoju dzieci", "Zdrowie i kultura fizyczna"], "poprawna": [2, 3, 0, 1], "wyjasnienie": "Algiz – wczesne wspomaganie rozwoju dzieci, Kinesis – zdrowie i kultura fizyczna, Art of Dining – gastronomia, Q Marzeniom – eventy i szkolenia."}'::jsonb),
  (26, 'wybor', 'Do kiedy przedsiębiorstwo społeczne musi złożyć coroczne sprawozdanie, aby utrzymać status PS?', 20, '{"odpowiedzi": ["Do 31 grudnia", "Do 31 marca", "Do 31 stycznia", "Do 31 czerwca"], "poprawna": 1, "wyjasnienie": "Do 31 marca roku następującego po roku sprawozdawczym. Niezłożenie sprawozdania grozi utratą statusu PS. A 31 czerwca w ogóle nie istnieje!"}'::jsonb),
  (27, 'wybor', 'Wskaż przedsiębiorstwa społeczne z naszego subregionu działające w branży remontowo-budowlanej.', 40, '{"odpowiedzi": ["Stowarzyszenie Pomocy Osobom z Autyzmem, Stowarzyszenie „Druga Szansa”, Fundacja Dzieci Wuja Toma", "Fundacja Anmed Lubię Cię, Fundacja Wesoło Mi, Niebo w Mieście Sp. z o.o.", "Fundacja „Rozwijamy Talenty”, Fundacja Efekty, Częstochowska Organizacja Turystyczna", "Fundacja Ecostructure, Eco-Renewal Sp. z o.o., Spółdzielnia Socjalna „Jasne, że dom i wnętrze”, FHU Sin-Bud"], "poprawna": 3, "wyjasnienie": "Remonty i budowlanka to Fundacja Ecostructure, Eco-Renewal, SS „Jasne, że dom i wnętrze” i FHU Sin-Bud. Pozostałe zestawy działają w innych branżach."}'::jsonb),
  (28, 'wybor', 'Jak się nazywa obowiązkowy organ w przedsiębiorstwie społecznym, który m.in. zapoznaje się z wynikami działalności i opiniuje planowane działania PS?', 30, '{"odpowiedzi": ["Organ opiniujący", "Rada kolegialna", "Organ konsultacyjno-doradczy", "Zebranie przedsiębiorstwa społecznego"], "poprawna": 2, "wyjasnienie": "To organ konsultacyjno-doradczy – element demokratycznego zarządzania w PS. Daje pracownikom wpływ na działalność przedsiębiorstwa."}'::jsonb),
  (29, 'wybor', 'Wskaż przedsiębiorstwa społeczne z naszego subregionu realizujące usługi społeczne z zakresu kultury.', 40, '{"odpowiedzi": ["Stowarzyszenie Muzeum 303 im. ppłk. pil. Jana Zumbacha, Fundacja Gutenberg na rzecz Kultury i Nauki", "Spółdzielnia Socjalna „Jasne, że bus”, Stowarzyszenie Pomocy Potrzebującym „Podaj dalej”", "Śląska Fundacja Wspierania Rozwoju Społeczno-Zawodowego Juventas, Fundacja Talbota", "Fundacja Pomocy Kobietom EuroHelp, Fundacja Animalove"], "poprawna": 0, "wyjasnienie": "Usługi z zakresu kultury realizują Stowarzyszenie Muzeum 303 im. ppłk. pil. Jana Zumbacha i Fundacja Gutenberg na rzecz Kultury i Nauki."}'::jsonb),
  (30, 'kolejnosc', 'Jakie są etapy uzyskiwania dotacji w JOWES? Ułóż je we właściwej kolejności.', 40, '{"elementy": ["Podpisanie umowy", "Formularz Pomysłu", "Przelew środków", "Biznesplan", "Zabezpieczenie finansowe"], "poprawna": [1, 3, 4, 0, 2], "wyjasnienie": "Najpierw Formularz Pomysłu, potem biznesplan, zabezpieczenie finansowe, podpisanie umowy i na końcu przelew środków."}'::jsonb),
  (31, 'wybor', 'Co oznacza skrót BUR?', 20, '{"odpowiedzi": ["Biuro Usług Regionalnych", "Baza Usług Rozwojowych", "Bank Uniwersalnych Rozwiązań", "Baza Umów Rekrutacyjnych"], "poprawna": 1, "wyjasnienie": "BUR to Baza Usług Rozwojowych prowadzona przez PARP – szkolenia i doradztwo z dofinansowaniem. Szkolenia z możliwością dofinansowania realizuje też uczestnik Forum – Invelion Sp. z o.o."}'::jsonb),
  (32, 'wybor', 'Które z wymienionych przedsiębiorstw społecznych działają na rzecz ekologii i zrównoważonego rozwoju?', 35, '{"odpowiedzi": ["Invelion Sp. z o.o., Fundacja Talbota", "Spółdzielnia Socjalna „Jasne, że zmiana”, VERTO Biuro Rachunkowe Sp. z o.o.", "Fundacja Kreatywna Przestrzeń, Stowarzyszenie Muzeum 303", "Fundacja Eko-Logiczna, Fundacja Rething", "Fundacja Projekt: Rozwój, Fundacja Algiz"], "poprawna": 3, "wyjasnienie": "Ekologią i zrównoważonym rozwojem zajmują się Fundacja Eko-Logiczna i Fundacja Rething."}'::jsonb),
  (33, 'wielokrotny', 'Kto może zrobić dla Was warsztaty edukacyjne dla dzieci? Zaznacz wszystkie poprawne.', 45, '{"odpowiedzi": ["Fundacja Przylądek Kreatywności", "Fundacja Kinesis", "MIMAWI Sp. z o.o.", "Adullam Sp. z o.o.", "Fundacja Kreatywna Przestrzeń", "Osikowa Dolina Sp. z o.o.", "Sin-Bud Sp. z o.o.", "Fundacja Wesoło Mi"], "poprawna": [0, 2, 4, 5, 7], "wyjasnienie": "Warsztaty dla dzieci prowadzą: Przylądek Kreatywności, Wesoło Mi, Kreatywna Przestrzeń z Kłobucka (warsztaty artystyczne i wakacyjne), MIMAWI (zajęcia edukacyjne i warsztaty techniczne) oraz Osikowa Dolina (warsztaty z drewna topoli osiki)."}'::jsonb),
  (34, 'wybor', 'Które stwierdzenie najtrafniej opisuje różnicę między podmiotem ekonomii społecznej (PES) a przedsiębiorstwem społecznym (PS)?', 40, '{"odpowiedzi": ["PES prowadzi wyłącznie działalność nieodpłatną, a PS wyłącznie działalność gospodarczą.", "PES to szeroka kategoria podmiotów, natomiast PS to podmiot posiadający szczególny status przyznany na podstawie ustawy.", "Każdy PES jest przedsiębiorstwem społecznym, ale nie każde PS jest organizacją pozarządową.", "Przedsiębiorstwo społeczne jest odrębną formą prawną, niezależną od fundacji i stowarzyszeń."], "poprawna": 1, "wyjasnienie": "PES to m.in. fundacja, stowarzyszenie, spółdzielnia socjalna czy CIS. Przedsiębiorstwo społeczne nie jest osobną formą prawną, lecz statusem, który PES może uzyskać po spełnieniu ustawowych warunków."}'::jsonb),
  (35, 'wybor', 'Który z poniższych podmiotów należy do katalogu podmiotów ekonomii społecznej?', 35, '{"odpowiedzi": ["Każda jednoosobowa działalność gospodarcza realizująca usługi dla seniorów.", "Każda spółka akcyjna, niezależnie od celu i sposobu działania.", "Fundacja prowadząca działalność statutową na rzecz społeczności lokalnej.", "Każda spółka prawa handlowego, która zatrudnia osoby bezrobotne."], "poprawna": 2, "wyjasnienie": "Fundacje to organizacje pozarządowe, które ustawa o ekonomii społecznej zalicza do PES. Samo zatrudnianie osób zagrożonych wykluczeniem nie czyni firmy PES. Spółki mogą być PES tylko wtedy, gdy działają nie dla zysku."}'::jsonb),
  (36, 'pary', 'Kto czym się zajmuje? Połącz uczestnika Forum z jego działalnością.', 45, '{"lewe": ["VERTO Biuro Rachunkowe Sp. z o.o.", "Invelion Sp. z o.o.", "Fundacja Projekt: Rozwój", "Fundacja Kreatywna Przestrzeń", "Fundacja Kuźnia Pomysłów"], "prawe": ["Alpakoterapia – Alpaka Love", "Sprzątanie i atrakcje dla dzieci", "Księgowość i rachunkowość", "Szycie i znakowanie odzieży dla firm", "E-commerce, szkolenia i doradztwo"], "poprawna": [2, 4, 1, 3, 0], "wyjasnienie": "VERTO – biuro rachunkowe, Invelion – e-commerce, szkolenia i doradztwo, Projekt: Rozwój – sprzątanie i atrakcje dla dzieci, Kreatywna Przestrzeń – szycie dla firm (z zarobku finansuje warsztaty dla dzieci), Kuźnia Pomysłów – zajęcia z alpakami Alpaka Love."}'::jsonb),
  (37, 'wielokrotny', 'Które z tych podmiotów są związane z zakładem aktywności zawodowej (ZAZ)? Zaznacz wszystkie poprawne.', 35, '{"odpowiedzi": ["Stowarzyszenie YAVA", "VERTO Biuro Rachunkowe Sp. z o.o.", "Klubokawiarnia Alternatywa 21", "Fundacja Rething", "Premium Tour Szymczyk Sp. z o.o.", "Fundacja Q Marzeniom"], "poprawna": [0, 2], "wyjasnienie": "Stowarzyszenie YAVA prowadzi ZAZ, w którym pracuje 29 osób z niepełnosprawnością znaczną i umiarkowaną (a do tego Środowiskowy Dom Samopomocy i ośrodek dla osób z chorobą Alzheimera). Klubokawiarnię Alternatywa 21 też prowadzi ZAZ."}'::jsonb),
  (38, 'wybor', 'Ile miejsc pracy w PES/PS JOWES pomógł utworzyć w samym 2026 roku?', 20, '{"odpowiedzi": ["44", "14", "177", "570"], "poprawna": 0, "wyjasnienie": "44 miejsca pracy i prawie 3,9 mln zł dotacji dla NGO w 2026 roku. Do tego ponad 3 tys. godzin doradztwa i 14 dni szkoleniowych."}'::jsonb),
  (39, 'pary', 'Kto czym się zajmuje? Część 2 – połącz uczestnika Forum z jego ofertą.', 45, '{"lewe": ["Fundacja Czas na Seniora", "Fundacja Muzyki Niezależnej", "Premium Tour Szymczyk Sp. z o.o.", "Fundacja Propagowania Zdrowego Odżywiania MIDEX", "Fundacja Doktor Elsner"], "prawe": ["Kolonie, obozy i turystyka wytchnieniowa", "Dietetyka kliniczna i profilaktyka zdrowotna", "Nagłośnienie koncertów i wydawnictwo muzyczne", "Taksówka Społeczna i Pogotowie „Złota Rączka”", "Wędliny, garmaż i catering"], "poprawna": [3, 2, 0, 4, 1], "wyjasnienie": "Czas na Seniora – ogrody, Taksówka Społeczna, „Złota Rączka”; Muzyka Niezależna – obsługa wydarzeń, edukacja, wydawnictwo; Premium Tour Szymczyk – biuro podróży; MIDEX – produkcja spożywcza, catering i edukacja żywieniowa; Doktor Elsner – zdrowie funkcjonalne, dietetyka, kosmetologia."}'::jsonb),
  (40, 'pary', 'Kto czym się zajmuje? Część 3 – połącz uczestnika Forum z jego ofertą.', 45, '{"lewe": ["Osikowa Dolina Sp. z o.o.", "Fundacja „Dzikie Serce”", "MIMAWI Sp. z o.o.", "Fundacja Rething", "Fundacja Q Marzeniom"], "prawe": ["Sadzenie drzew i sprzątanie brzegów Warty", "Pracownia rękodzieła i warsztaty artystyczne", "Agencja social-mediowa: eventy i content", "Dekoracje i warsztaty z drewna topoli osiki", "Warsztaty techniczne i majsterkowanie"], "poprawna": [3, 1, 4, 0, 2], "wyjasnienie": "Osikowa Dolina tworzy dekoracje z wiórków osikowych, Dzikie Serce sprzedaje wyroby ze swojej pracowni i prowadzi warsztaty, MIMAWI uczy majsterkowania i prowadzi zajęcia dla seniorów, Rething działa dla klimatu od 2019 r., a Q Marzeniom organizuje wydarzenia i produkuje content."}'::jsonb),
  (41, 'wielokrotny', 'Planujecie wydarzenie. Kto z uczestników Forum pomoże je zorganizować lub obsłużyć? Zaznacz wszystkie poprawne.', 40, '{"odpowiedzi": ["Fundacja Muzyki Niezależnej", "VERTO Biuro Rachunkowe Sp. z o.o.", "Fundacja Q Marzeniom", "Sin-Bud Sp. z o.o.", "Fundacja Art of Dining", "Fundacja Czas na Seniora", "Fundacja Kreatywna Przestrzeń"], "poprawna": [0, 2, 4, 6], "wyjasnienie": "Nagłośnienie i oprawę zapewni Fundacja Muzyki Niezależnej, organizację i content – Q Marzeniom, kolację lub wydarzenie kulturalne – Art of Dining, a wydarzenie plenerowe – Kreatywna Przestrzeń. VERTO to księgowość, Sin-Bud – budowlanka, Czas na Seniora – ogrody i Taksówka Społeczna."}'::jsonb),
  (42, 'wielokrotny', 'Kto zadba o Wasze zdrowie i dobrą formę? Zaznacz wszystkie poprawne.', 35, '{"odpowiedzi": ["Kinesis Sp. z o.o.", "Sin-Bud Sp. z o.o.", "Fundacja Doktor Elsner", "VERTO Biuro Rachunkowe Sp. z o.o.", "Fundacja Propagowania Zdrowego Odżywiania MIDEX", "Eco Renewal Sp. z o.o."], "poprawna": [0, 2, 4], "wyjasnienie": "Kinesis – fizjoterapia, rehabilitacja i siłownia; Doktor Elsner – dietetyka kliniczna i profilaktyka zdrowotna; MIDEX – edukacja o zdrowym odżywianiu."}'::jsonb),
  (43, 'wielokrotny', 'Które z tych podmiotów mają ofertę dla seniorów? Zaznacz wszystkie poprawne.', 40, '{"odpowiedzi": ["Fundacja Czas na Seniora", "Eco Renewal Sp. z o.o.", "MIMAWI Sp. z o.o.", "Invelion Sp. z o.o.", "Premium Tour Szymczyk Sp. z o.o.", "VERTO Biuro Rachunkowe Sp. z o.o.", "Kinesis Sp. z o.o."], "poprawna": [0, 2, 4, 6], "wyjasnienie": "Czas na Seniora („Razem łatwiej!” – Taksówka Społeczna, „Złota Rączka”), MIMAWI (zajęcia aktywizacyjne dla seniorów), Premium Tour Szymczyk (turystyka dla seniorów) i Kinesis (fizjoterapia i siłownia m.in. dla seniorów)."}'::jsonb),
  (44, 'ciekawostka', 'Dziękujemy! Na Forum Współpracy Przedsiębiorstw Społecznych byli z nami:', null, '{"tekst": "Adullam Sp. z o.o.  ·  Stowarzyszenie Wzajemnej Pomocy „Agape”  ·  Fundacja Akademia Przygody  ·  Fundacja Akademia z Pasją  ·  Fundacja Algiz  ·  Fundacja Art of Dining  ·  Fundacja Czas na Seniora  ·  Fundacja Doktor Elsner  ·  Stowarzyszenie „Druga Szansa”  ·  Fundacja Dzieci Wuja Toma  ·  Fundacja Dzikie Serce  ·  Eco Renewal Sp. z o.o.  ·  Fundacja Ecostructure  ·  Fundacja Eko-Logiczna  ·  Invelion Sp. z o.o.  ·  Spółdzielnia Socjalna „Jasne, że alternatywa 21”  ·  Spółdzielnia Socjalna „Jasne, że dom i wnętrze”  ·  Fundacja Kinesis  ·  Kinesis Sp. z o.o.  ·  Fundacja Kreatywna Przestrzeń  ·  Fundacja Kuźnia Pomysłów  ·  MIMAWI Sp. z o.o.  ·  Stowarzyszenie Muzeum 303  ·  Fundacja Muzyki Niezależnej  ·  Niebo w Mieście Częstochowa  ·  Osikowa Dolina Sp. z o.o.  ·  Fundacja Pomocna  ·  Fundacja Pomocy Kobietom EuroHelp  ·  Stowarzyszenie Pomocy Osobom z Autyzmem  ·  Premium Tour Szymczyk Sp. z o.o.  ·  Fundacja Projekt: Rozwój  ·  Fundacja Propagowania Zdrowego Odżywiania MIDEX  ·  Fundacja „Przyjaciel z Sercem”  ·  Fundacja Q Marzeniom  ·  Fundacja Radosne Chwile  ·  Fundacja Rething  ·  Fundacja „Rozwijamy Talenty”  ·  Sin-Bud Sp. z o.o.  ·  Fundacja Talbota  ·  Fundacja Twoja Zagata  ·  VERTO Biuro Rachunkowe Sp. z o.o.  ·  Stowarzyszenie YAVA"}'::jsonb)
) as v(nr, typ, tresc, czas_s, dane);
